"""Repo hygiene checks: conflict markers, secret patterns, role-prompt byte budget.

Each check is a pure function over (path, text) pairs. Fixture tests exercise
the reject and accept paths; the repo-wide tests run the same functions over
the tracked files. Marker and token strings are assembled at runtime so this
file never matches its own scans.
"""
import re
import subprocess
import unittest
from pathlib import Path
import _gitenv  # noqa: F401  (hermetic git: tests/_gitenv.py)

ROOT = Path(__file__).resolve().parent.parent

# Generated by the tick and quoting arbitrary DB text: never scanned.
SKIP_PREFIXES = ("exports/", "state/")

# Raising this is its own PR. Prefer moving detail into a per-role skill under
# roles/plugins/<role>/ instead of growing the always-loaded role prompts.
ROLE_PROMPT_BUDGET_BYTES = 12000

# Fail-fast target: a pair drifting past this is caught before it nears the budget.
ROLE_PROMPT_TARGET_BYTES = 10800

_OPEN = "<" * 7
_CLOSE = ">" * 7

ALLOW_MARKER = "secret-scan: " + "allow"

SECRET_PATTERNS = (
    ("github-token", re.compile(r"\bgh[pousr]" + "_" + r"[A-Za-z0-9]{36,}")),
    ("github-pat", re.compile(r"\bgithub" + "_pat_" + r"[A-Za-z0-9_]{22,}")),
    ("anthropic-key", re.compile(r"\bsk" + "-ant-" + r"[A-Za-z0-9_-]{20,}")),
    ("aws-access-key-id", re.compile(r"\bAK" + "IA" + r"[A-Z0-9]{16}")),
    ("pem-private-key", re.compile("-----" + "BEGIN " + r"[A-Z ]*" + "PRIVATE " + "KEY" + "-----")),
    ("slack-token", re.compile(r"\bxox[abprs]" + "-" + r"[A-Za-z0-9-]{10,}")),
)


def _skipped(path):
    return path.startswith(SKIP_PREFIXES)


def find_conflict_markers(files):
    """Return 'path:line' for each line starting with a conflict marker."""
    found = []
    for path, text in files:
        if _skipped(path):
            continue
        for n, line in enumerate(text.splitlines(), 1):
            for mark in (_OPEN, _CLOSE):
                if line == mark or line.startswith(mark + " "):
                    found.append(f"{path}:{n}")
    return found


def find_secrets(files):
    """Return 'path:line pattern-name' per hit. Never includes the matched value."""
    found = []
    for path, text in files:
        if _skipped(path):
            continue
        for n, line in enumerate(text.splitlines(), 1):
            if ALLOW_MARKER in line:
                continue
            for name, rx in SECRET_PATTERNS:
                if rx.search(line):
                    found.append(f"{path}:{n} {name}")
    return found


def check_role_budget(sizes, budget=None):
    """sizes: {role: (common_bytes, role_bytes)}. Return one message per over-budget role."""
    budget = ROLE_PROMPT_BUDGET_BYTES if budget is None else budget
    out = []
    for role, (common, own) in sorted(sizes.items()):
        total = common + own
        if total > budget:
            out.append(f"role {role}: {total} bytes (_common {common} + {role} {own}) > budget {budget}; "
                       "raising the budget is its own PR, prefer moving detail into a per-role skill "
                       f"under roles/plugins/{role}/")
    return out


def check_role_target(sizes, target=None):
    """sizes: {role: (common_bytes, role_bytes)}. Return one message per role over the target."""
    target = ROLE_PROMPT_TARGET_BYTES if target is None else target
    out = []
    for role, (common, own) in sorted(sizes.items()):
        total = common + own
        if total > target:
            out.append(f"role {role}: {total} bytes (_common {common} + {role} {own}) > target {target}; "
                       f"fix: move detail into roles/plugins/{role}/ (a skill) and leave a one-line pointer in roles/{role}.md")
    return out


def inside_git_work_tree(path=None):
    path = ROOT if path is None else path
    try:
        r = subprocess.run(["git", "rev-parse", "--is-inside-work-tree"], cwd=path, capture_output=True, text=True)
    except OSError:
        return False
    return r.returncode == 0 and r.stdout.strip() == "true"


def require_git_work_tree(case):
    if not inside_git_work_tree():
        case.skipTest("repo-wide scan needs a git work tree (git rev-parse --is-inside-work-tree failed)")


def tracked_text_files():
    out = subprocess.run(["git", "ls-files", "-z"], cwd=ROOT, capture_output=True, check=True).stdout
    files = []
    for rel in out.decode().split("\0"):
        if not rel or _skipped(rel):
            continue
        p = ROOT / rel
        if not p.is_file():
            continue
        data = p.read_bytes()
        if b"\0" in data:
            continue
        try:
            files.append((rel, data.decode("utf-8")))
        except UnicodeDecodeError:
            continue
    return files


def real_role_sizes():
    roles = ROOT / "roles"
    common = len((roles / "_common.md").read_bytes())
    return {p.stem: (common, len(p.read_bytes())) for p in sorted(roles.glob("*.md")) if p.name != "_common.md"}


class ConflictMarkerTests(unittest.TestCase):
    def test_hygiene_markers_flagged_with_path_and_line(self):
        text = f"ok\n{_OPEN} HEAD\nmine\n{_CLOSE} branch\n{_OPEN}\n"
        self.assertEqual(find_conflict_markers([("a/b.md", text)]), ["a/b.md:2", "a/b.md:4", "a/b.md:5"])

    def test_hygiene_markers_ignore_setext_and_midline(self):
        text = f"Title\n=======\n\nsee {_OPEN} in the middle\n x {_CLOSE} y\n{_OPEN}x\n"
        self.assertEqual(find_conflict_markers([("a.md", text)]), [])

    def test_hygiene_markers_skip_generated_dirs(self):
        text = f"{_OPEN} HEAD\n"
        files = [("exports/x.md", text), ("state/y.sql", text)]
        self.assertEqual(find_conflict_markers(files), [])
        self.assertEqual(find_secrets([("exports/x.md", "gh" + "p_" + "A" * 36)]), [])

    def test_hygiene_markers_repo_clean(self):
        require_git_work_tree(self)
        self.assertEqual(find_conflict_markers(tracked_text_files()), [])


class SecretTests(unittest.TestCase):
    SAMPLES = {
        "github-token": "gh" + "p_" + "a1B2" * 9,
        "github-pat": "github" + "_pat_" + "A1b2C3" * 4,
        "anthropic-key": "sk" + "-ant-" + "abc_DEF-123" * 3,
        "aws-access-key-id": "AK" + "IA" + "ABCDEFGH12345678",
        "pem-private-key": "-----" + "BEGIN RSA " + "PRIVATE " + "KEY" + "-----",
        "slack-token": "xox" + "b-" + "1234567890-abcdef",
    }

    def test_hygiene_secret_each_pattern_flagged_without_value(self):
        for name, sample in self.SAMPLES.items():
            with self.subTest(pattern=name):
                got = find_secrets([("cfg/x.txt", f"x\nkey = {sample}\n")])
                self.assertEqual(got, [f"cfg/x.txt:2 {name}"])
                self.assertNotIn(sample, got[0])

    def test_hygiene_secret_other_gh_prefixes(self):
        for pre in ("gho_", "ghu_", "ghs_", "ghr_"):
            self.assertEqual(len(find_secrets([("a", pre + "z" * 40)])), 1, pre)

    def test_hygiene_secret_allow_marker_exempts_line(self):
        line = f"{self.SAMPLES['github-token']}  # {ALLOW_MARKER}\n"
        self.assertEqual(find_secrets([("t.py", line)]), [])

    def test_hygiene_secret_short_or_plain_text_accepted(self):
        text = "gh" + "p_short\nsk" + "-ant-x\nAK" + "IA123\nplain prose\n"
        self.assertEqual(find_secrets([("a.md", text)]), [])

    def test_hygiene_secret_repo_clean(self):
        require_git_work_tree(self)
        self.assertEqual(find_secrets(tracked_text_files()), [])


class NoGitTreeTests(unittest.TestCase):
    def test_hygiene_repo_scan_skips_outside_git_work_tree(self):
        import tempfile
        with tempfile.TemporaryDirectory() as d:
            self.assertFalse(inside_git_work_tree(d))
            global ROOT
            saved = ROOT
            ROOT = Path(d)
            try:
                for case in (ConflictMarkerTests("test_hygiene_markers_repo_clean"),
                             SecretTests("test_hygiene_secret_repo_clean")):
                    name = case.id()
                    res = unittest.TestResult()
                    case.run(res)
                    self.assertEqual((len(res.skipped), len(res.failures), len(res.errors)), (1, 0, 0), name)
                    self.assertIn("git work tree", res.skipped[0][1])
            finally:
                ROOT = saved

    def test_hygiene_inside_git_work_tree_true_for_repo(self):
        require_git_work_tree(self)
        self.assertTrue(inside_git_work_tree())


class RoleBudgetTests(unittest.TestCase):
    def test_hygiene_budget_over_flagged_with_details(self):
        msgs = check_role_budget({"big": (5000, 7001), "small": (5000, 100)}, budget=12000)
        self.assertEqual(len(msgs), 1)
        for needle in ("big", "12001", "12000", "roles/plugins/big/", "own PR"):
            self.assertIn(needle, msgs[0])

    def test_hygiene_budget_at_limit_accepted(self):
        self.assertEqual(check_role_budget({"r": (6000, 6000)}, budget=12000), [])

    def test_hygiene_budget_real_roles(self):
        sizes = real_role_sizes()
        self.assertTrue(sizes)
        self.assertNotIn("_common", sizes)
        self.assertEqual(check_role_budget(sizes), [])

    def test_hygiene_target_over_flagged_with_role_size_and_fix(self):
        msgs = check_role_target({"big": (6000, 4801), "small": (6000, 4800)})
        self.assertEqual(len(msgs), 1)
        for needle in ("big", "10801", "10800", "move detail into roles/plugins/big/"):
            self.assertIn(needle, msgs[0])

    def test_hygiene_target_at_limit_accepted(self):
        self.assertEqual(check_role_target({"r": (6000, 4800)}), [])

    def test_hygiene_target_real_roles(self):
        sizes = real_role_sizes()
        self.assertTrue(sizes)
        self.assertEqual(check_role_target(sizes), [])


if __name__ == "__main__":
    unittest.main()
